/**
 * Config plugin: point the Android `release` build type at a real keystore.
 *
 * `android/` is generated by `expo prebuild`, so hand-edits to
 * `app/build.gradle` are lost on the next prebuild. This re-applies the
 * release signing config every time, reading credentials from env vars so
 * they stay out of the repo.
 *
 * Env (all optional; defaults match the checked-in dev keystore):
 *   MENUMATE_KEYSTORE_FILE, MENUMATE_KEYSTORE_PASSWORD,
 *   MENUMATE_KEY_ALIAS, MENUMATE_KEY_PASSWORD
 */
const { withAppBuildGradle } = require("expo/config-plugins");

const RELEASE_CONFIG = `        release {
            storeFile file(System.getenv("MENUMATE_KEYSTORE_FILE") ?: "menumate-release.keystore")
            storePassword System.getenv("MENUMATE_KEYSTORE_PASSWORD") ?: "menumate-release"
            keyAlias System.getenv("MENUMATE_KEY_ALIAS") ?: "menumate"
            keyPassword System.getenv("MENUMATE_KEY_PASSWORD") ?: "menumate-release"
        }
`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents;

    // 1. Add a `release` entry alongside the generated `debug` signingConfig.
    //    Keyed off the env-var marker, not a bare `release {` match -- the
    //    `buildTypes` block further down also contains a `release {`.
    if (!gradle.includes("MENUMATE_KEYSTORE_FILE")) {
      gradle = gradle.replace(
        /(signingConfigs\s*\{\n)/,
        `$1${RELEASE_CONFIG}`
      );
    }

    // 2. Make the release build type use it instead of the debug key.
    gradle = gradle.replace(
      /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/,
      "$1signingConfig signingConfigs.release"
    );

    cfg.modResults.contents = gradle;
    return cfg;
  });
};
